import{_ as a,o as t,c as o,a5 as i}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"3.4.16 Leave Workspace","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-16-leave-workspace/spec.md","filePath":"feature/agency-workspace/3-4-16-leave-workspace/spec.md"}'),r={name:"feature/agency-workspace/3-4-16-leave-workspace/spec.md"};function s(n,e,l,c,h,d){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="_3-4-16-leave-workspace" tabindex="-1">3.4.16 Leave Workspace <a class="header-anchor" href="#_3-4-16-leave-workspace" aria-label="Permalink to &quot;3.4.16 Leave Workspace&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>FR Code</td><td>3.4.16</td></tr><tr><td>Feature</td><td>Leave Workspace</td></tr><tr><td>Domain</td><td>Agency &amp; Workspace (FR 3.4)</td></tr><tr><td>Role</td><td>MANAGER / CREATOR / CLIENT (any active member leaving their own Workspace)</td></tr><tr><td>Version</td><td>3.1 — 2026-09-23 — rewritten to the standard FR format</td></tr><tr><td>Document status</td><td>Implemented</td></tr></tbody></table><h2 id="function-trigger" tabindex="-1">Function Trigger <a class="header-anchor" href="#function-trigger" aria-label="Permalink to &quot;Function Trigger&quot;">​</a></h2><p>Begins when an active member of a Workspace confirms leaving that Workspace.</p><h2 id="function-description" tabindex="-1">Function Description <a class="header-anchor" href="#function-description" aria-label="Permalink to &quot;Function Description&quot;">​</a></h2><ul><li><strong>Actors / Roles:</strong> Any active member of the Workspace — MANAGER, CREATOR, or CLIENT — acting on their own membership only.</li><li><strong>Purpose:</strong> Lets a member leave a Workspace they no longer take part in while keeping their Agency membership, so they can still join other Workspaces.</li><li><strong>Interface:</strong> &quot;Leave Workspace&quot; action in Workspace settings or the members screen, shown only to the signed-in user themselves, followed by a confirmation dialog.</li><li><strong>Data Processing:</strong> The system locates the caller&#39;s own active membership in the Workspace and marks it inactive, without touching the caller&#39;s Agency membership.</li></ul><h2 id="screen-layout" tabindex="-1">Screen Layout <a class="header-anchor" href="#screen-layout" aria-label="Permalink to &quot;Screen Layout&quot;">​</a></h2><p>Figure — Leave Workspace Dialog:</p><ul><li>A &quot;Leave Workspace&quot; action inside Workspace settings or the members screen, visible only to the signed-in user.</li><li>A confirmation dialog explaining that the member leaves this Workspace but remains in the Agency.</li><li>A blocked state with a clear message when the member is the last MANAGER of the Workspace.</li></ul><h2 id="function-details" tabindex="-1">Function Details <a class="header-anchor" href="#function-details" aria-label="Permalink to &quot;Function Details&quot;">​</a></h2><h3 id="data-specifications" tabindex="-1">Data Specifications <a class="header-anchor" href="#data-specifications" aria-label="Permalink to &quot;Data Specifications&quot;">​</a></h3><ul><li><strong>Input required:</strong> The Workspace identifier; the caller&#39;s authenticated identity (taken from the session principal, never from the request).</li><li><strong>Input optional:</strong> None.</li><li><strong>System data:</strong> The caller&#39;s active membership row in that Workspace; the count of active MANAGERs in the Workspace.</li><li><strong>Output:</strong> Confirmation that the membership has been deactivated; no other data is returned.</li></ul><h3 id="business-rules" tabindex="-1">Business Rules <a class="header-anchor" href="#business-rules" aria-label="Permalink to &quot;Business Rules&quot;">​</a></h3><ul><li><strong>BR-29:</strong> Multi-tenancy — the caller identity always comes from the session principal and the action applies only to the caller&#39;s own membership row in that workspace; no other member can be targeted.</li><li><strong>BR-28 / BR-30:</strong> Leaving is a soft delete (<code>isActive=false</code>, not a row deletion): the caller&#39;s membership is marked inactive; a member who leaves loses access immediately because every scoped query re-checks membership. The caller&#39;s Agency membership is never modified, so they remain in the Agency and in their other Workspaces. BR-28&#39;s last-manager protection also applies to leaving: a MANAGER cannot leave if they are the last active MANAGER of the Workspace; the MANAGER role must be handed over first through FR 3.4.20 Update Workspace Member Role.</li><li><strong>BR-31:</strong> The Workspace role set is OWNER, MANAGER, CREATOR, CLIENT (<code>MemberRole</code> enum); at Workspace level only MANAGER, CREATOR, CLIENT are assignable, and the last-MANAGER guard applies only when the membership being deactivated carries the MANAGER role.</li></ul><h3 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h3><ul><li>The caller must hold an active membership in that Workspace; otherwise 403 <code>WORKSPACE_ACCESS_DENIED</code>, toast MSG40.</li><li>The caller must not be the only active MANAGER of the Workspace (BR-28); otherwise 409 <code>LAST_MANAGER_CANNOT_BE_REMOVED</code>, toast MSG37.</li></ul><h2 id="functionalities" tabindex="-1">Functionalities <a class="header-anchor" href="#functionalities" aria-label="Permalink to &quot;Functionalities&quot;">​</a></h2><h3 id="normal-flow" tabindex="-1">Normal Flow <a class="header-anchor" href="#normal-flow" aria-label="Permalink to &quot;Normal Flow&quot;">​</a></h3><ol><li>Member opens Workspace settings or the members screen and chooses &quot;Leave Workspace&quot;.</li><li>Member confirms in the dialog.</li><li>System looks up the caller&#39;s own active membership in the Workspace; if none exists the request fails with 403 <code>WORKSPACE_ACCESS_DENIED</code>.</li><li>System applies the last-MANAGER guard (BR-28): members who are not MANAGER pass, and a MANAGER passes when another active MANAGER exists.</li><li>System marks the membership inactive (BR-28/BR-30 soft delete).</li><li>The member is taken out of the Workspace back to the Workspace list, while remaining in the Agency and in their other Workspaces; toast MSG36.</li></ol><h3 id="abnormal-cases" tabindex="-1">Abnormal Cases <a class="header-anchor" href="#abnormal-cases" aria-label="Permalink to &quot;Abnormal Cases&quot;">​</a></h3><ul><li>3.a1: Caller has no active membership in that Workspace (BR-29) → 403 <code>WORKSPACE_ACCESS_DENIED</code>, toast MSG40. 3.a2: The caller returns to the Workspace list; the Workspace they tried to leave does not appear.</li><li>4.a1: Caller is the only active MANAGER of the Workspace (BR-28) → 409 <code>LAST_MANAGER_CANNOT_BE_REMOVED</code>, toast MSG37. 4.a2: Another MANAGER must be assigned first through FR 3.4.20 Update Workspace Member Role, then the caller retries leaving.</li><li>4.b1: A CREATOR or CLIENT leaves while other members remain (BR-28 does not apply to non-MANAGER roles) → the request always succeeds. 4.b2: The member is removed from the Workspace and returned to the Workspace list.</li><li>3.b1: The action is invoked twice in a row → the second call finds no active membership and fails with 403 <code>WORKSPACE_ACCESS_DENIED</code>, toast MSG40. 3.b2: The caller is already out of the Workspace, so no further action is needed.</li></ul><h2 id="post-conditions" tabindex="-1">Post-Conditions <a class="header-anchor" href="#post-conditions" aria-label="Permalink to &quot;Post-Conditions&quot;">​</a></h2><ul><li>The caller&#39;s membership in the Workspace is inactive and the Workspace no longer appears in their list.</li><li>The caller&#39;s Agency membership is untouched; they remain in the Agency and in their other Workspaces.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>Automatically choosing a replacement MANAGER when the only MANAGER leaves (the handover must be done beforehand through FR 3.4.20).</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><p><a href="./../../../BA/01-organization-structure.html">01-organization-structure.md</a>, <a href="./../../../BA/03-agency-workspace-management.html">03-agency-workspace-management.md</a></p>',27)])])}const u=a(r,[["render",s]]);export{p as __pageData,u as default};
